where id=194;
update public.lessons
set content='{"intro": "Esta aula transforma «Como começar uma análise de terreno» numa competência de trabalho. No final, deverá conseguir reconhecer a situação, localizar a informação relevante, fazer as verificações essenciais, explicar o resultado ao cliente com rigor e identificar quando é necessária validação especializada.", "sections": [{"title": "O que deve dominar", "body": "RAN e REN são regimes de condicionamento territorial distintos. O formando deve saber identificar a incidência cartográfica e depois consultar o regime aplicável à ação pretendida, evitando respostas absolutas."}, {"title": "Como aplicar na prática", "body": "Confirmar delimitação oficial; identificar a ação concreta; verificar exceções/compatibilidades/procedimentos; registar a data da consulta e a entidade competente quando necessário."}, {"title": "O que confirmar antes de concluir", "body": "Dizer simplesmente ''está em RAN/REN, não constrói'' ou ''há casas ao lado, logo constrói'' é tecnicamente insuficiente."}, {"title": "Exemplo profissional", "body": "Exemplo: a mesma condicionante pode ter efeitos diferentes consoante o uso, a operação e o enquadramento específico."}, {"title": "Erros que deve evitar", "body": "• Repetir informação do proprietário como se estivesse verificada.\n• Usar um documento para provar matéria que pertence a outra fonte.\n• Ignorar a data, validade ou versão consultada.\n• Transformar uma estimativa ou possibilidade em certeza comercial.\n• Omitir uma divergência material por receio de dificultar o negócio."}, {"title": "Limite profissional", "body": "O consultor deve saber localizar informação, detetar riscos e formular perguntas. A interpretação técnica de projeto, a confirmação de edificabilidade e a definição do procedimento urbanístico devem ser validadas por arquiteto, engenheiro, município ou outro técnico competente quando o caso o exija."}], "takeaway": "Competência concluída: saber tratar «Como começar uma análise de terreno» com fonte, método, limites profissionais e comunicação transparente.", "case_title": "Aplicação prática", "case_body": "Exemplo: a mesma condicionante pode ter efeitos diferentes consoante o uso, a operação e o enquadramento específico."}'::jsonb,
