update public.lessons
set content='{"intro": "Esta aula transforma «Como ler o PDM sem ser urbanista» numa competência de trabalho. No final, deverá conseguir reconhecer a situação, localizar a informação relevante, fazer as verificações essenciais, explicar o resultado ao cliente com rigor e identificar quando é necessária validação especializada.", "sections": [{"title": "O que deve dominar", "body": "Ler um PDM implica combinar planta de ordenamento, planta de condicionantes e regulamento, identificando classificação/qualificação do solo, categoria de espaço, usos e parâmetros. Uma cor no mapa nunca é a conclusão final."}, {"title": "Como aplicar na prática", "body": "Localizar o prédio com precisão; identificar a categoria; ler a norma do regulamento; cruzar condicionantes; verificar planos mais específicos e regulamentos municipais; guardar data e versão consultadas."}, {"title": "O que confirmar antes de concluir", "body": "Solo urbano não significa automaticamente que qualquer construção é admissível. Forma do prédio, acessos, infraestruturas, servidões e parâmetros podem limitar a operação."}, {"title": "Exemplo profissional", "body": "Exemplo: categoria admite habitação, mas uma servidão e os afastamentos reduzem fortemente a implantação possível."}, {"title": "Erros que deve evitar", "body": "• Repetir informação do proprietário como se estivesse verificada.\n• Usar um documento para provar matéria que pertence a outra fonte.\n• Ignorar a data, validade ou versão consultada.\n• Transformar uma estimativa ou possibilidade em certeza comercial.\n• Omitir uma divergência material por receio de dificultar o negócio."}, {"title": "Limite profissional", "body": "O consultor deve saber localizar informação, detetar riscos e formular perguntas. A interpretação técnica de projeto, a confirmação de edificabilidade e a definição do procedimento urbanístico devem ser validadas por arquiteto, engenheiro, município ou outro técnico competente quando o caso o exija."}], "takeaway": "Competência concluída: saber tratar «Como ler o PDM sem ser urbanista» com fonte, método, limites profissionais e comunicação transparente.", "case_title": "Aplicação prática", "case_body": "Exemplo: categoria admite habitação, mas uma servidão e os afastamentos reduzem fortemente a implantação possível."}'::jsonb,
