update public.lessons
set content='{"intro": "Esta aula transforma «O que é o PIP e quando faz sentido» numa competência de trabalho. No final, deverá conseguir reconhecer a situação, localizar a informação relevante, fazer as verificações essenciais, explicar o resultado ao cliente com rigor e identificar quando é necessária validação especializada.", "sections": [{"title": "O que deve dominar", "body": "O PIP é um instrumento de informação prévia sobre determinada operação urbanística. Deve ser lido pelo pedido apresentado, decisão, condicionantes, elementos apreciados, prazo/efeitos e correspondência entre o cenário aprovado e o que se pretende comercializar."}, {"title": "Nota temporal · agosto de 2026", "body": "A revisão aprovada pelo Decreto-Lei n.º 108/2026 não deve ser tratada como já plenamente aplicável nesta data: o Decreto-Lei n.º 155-B/2026 prorrogou a entrada em vigor das alterações para 1 de outubro de 2026. Sempre que a aula descreva o novo regime, deve distingui-lo do regime em vigor até essa data e confirmar o regime transitório no caso concreto."}, {"title": "Como aplicar na prática", "body": "Confirmar requerente, prédio, operação, peças entregues, decisão e condicionantes. Verificar se o PIP é suficientemente detalhado para a conclusão que se pretende retirar e se continua temporalmente relevante."}, {"title": "O que confirmar antes de concluir", "body": "PIP favorável não equivale a licença de construção nem permite anunciar qualquer projeto. O conteúdo concreto e os seus efeitos dependem do procedimento e da legislação aplicável."}, {"title": "Exemplo profissional", "body": "Exemplo: PIP favorável para 4 moradias não sustenta anúncio ''aprovado para 6'' só porque um estudo posterior desenha 6 unidades."}, {"title": "Erros que deve evitar", "body": "• Repetir informação do proprietário como se estivesse verificada.\n• Usar um documento para provar matéria que pertence a outra fonte.\n• Ignorar a data, validade ou versão consultada.\n• Transformar uma estimativa ou possibilidade em certeza comercial.\n• Omitir uma divergência material por receio de dificultar o negócio."}, {"title": "Limite profissional", "body": "O consultor deve saber localizar informação, detetar riscos e formular perguntas. A interpretação técnica de projeto, a confirmação de edificabilidade e a definição do procedimento urbanístico devem ser validadas por arquiteto, engenheiro, município ou outro técnico competente quando o caso o exija."}], "takeaway": "Competência concluída: saber tratar «O que é o PIP e quando faz sentido» com fonte, método, limites profissionais e comunicação transparente.", "case_title": "Aplicação prática", "case_body": "Exemplo: PIP favorável para 4 moradias não sustenta anúncio ''aprovado para 6'' só porque um estudo posterior desenha 6 unidades."}'::jsonb,
    source_url='https://diariodarepublica.pt/dr/legislacao-consolidada/decreto-lei/1999-34567875-45232375',
    verified_at=date '2026-08-20',
