update public.lessons
set content='{"intro": "Esta aula transforma «Caso: vendedor anuncia “projeto aprovado”» numa competência de trabalho. No final, deverá conseguir reconhecer a situação, localizar a informação relevante, fazer as verificações essenciais, explicar o resultado ao cliente com rigor e identificar quando é necessária validação especializada.", "sections": [{"title": "O que deve dominar", "body": "O objetivo desta aula é dominar «Caso: vendedor anuncia “projeto aprovado”» no contexto de Casos práticos. O formando deve conseguir explicar o conceito, identificar a documentação ou informação necessária, reconhecer os principais riscos e saber qual é o próximo passo profissional."}, {"title": "Como aplicar na prática", "body": "Transforme «Caso: vendedor anuncia “projeto aprovado”» num procedimento: 1) definir o objetivo do cliente; 2) recolher fontes adequadas; 3) verificar atualidade e correspondência; 4) comparar com a realidade e outras fontes; 5) classificar divergências; 6) comunicar apenas conclusões suportadas; 7) encaminhar o que exigir competência especializada."}, {"title": "O que confirmar antes de concluir", "body": "Evite tratar «Caso: vendedor anuncia “projeto aprovado”» como uma formalidade. Pergunte sempre o que o dado/documento prova, o que não prova, se está atual e que efeito tem no negócio."}, {"title": "Exemplo profissional", "body": "Exemplo profissional: perante uma informação relacionada com «Caso: vendedor anuncia “projeto aprovado”» que não coincide com outro documento ou com a realidade, o consultor regista a divergência, não escolhe a versão mais conveniente e define a validação necessária antes de a apresentar como facto."}, {"title": "Erros que deve evitar", "body": "• Repetir informação do proprietário como se estivesse verificada.\n• Usar um documento para provar matéria que pertence a outra fonte.\n• Ignorar a data, validade ou versão consultada.\n• Transformar uma estimativa ou possibilidade em certeza comercial.\n• Omitir uma divergência material por receio de dificultar o negócio."}, {"title": "Limite profissional", "body": "O consultor deve saber localizar informação, detetar riscos e formular perguntas. A interpretação técnica de projeto, a confirmação de edificabilidade e a definição do procedimento urbanístico devem ser validadas por arquiteto, engenheiro, município ou outro técnico competente quando o caso o exija."}], "takeaway": "Competência concluída: saber tratar «Caso: vendedor anuncia “projeto aprovado”» com fonte, método, limites profissionais e comunicação transparente.", "case_title": "Aplicação prática", "case_body": "Exemplo profissional: perante uma informação relacionada com «Caso: vendedor anuncia “projeto aprovado”» que não coincide com outro documento ou com a realidade, o consultor regista a divergência, não escolhe a versão mais conveniente e define a validação necessária antes de a apresentar como facto."}'::jsonb,
    source_url='https://diariodarepublica.pt/dr/legislacao-consolidada/decreto-lei/1999-34567875-45232375',
    verified_at=date '2026-08-20',
    legal_sensitive=true
where id=229;
commit;

select c.title as formacao,
       count(*) as aulas,
       count(*) filter(where l.verified_at=date '2026-08-20') as verificadas_20082026
from public.courses c
join public.modules m on m.course_id=c.id
join public.lessons l on l.module_id=m.id
where c.slug='terrenos'
group by c.id,c.title;
